  "fim_base": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada termina em D10.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_99d51b6f67",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "A view não apresenta as precedências nem os requisitos de disponibilidade do cartucho da ficha relacional mencionada; não é possível determinar se a disponibilidade em D4 altera o caminho até o marco final."
    ],
    "motivo": "O aviso confirma a disponibilidade do substituto em D4 e o aceite do laudo, mas não fornece a relação necessária para calcular o término.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_99d51b6f67",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [
      "Sem as precedências e os requisitos de disponibilidade, não se determina o término novo para compará-lo com D10."
    ],
    "motivo": "Não há suporte visível para afirmar se o evento altera o término final ou em quantos dias.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "O orçamento de referência é R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_99d51b6f67",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "O término novo não pode ser calculado sem as precedências e os requisitos de disponibilidade; portanto, não se determina se haverá incidência de extensão além de D10."
    ],
    "motivo": "A troca não tem cobrança adicional, mas o custo total pode depender da extensão, que depende do término não determinável.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_99d51b6f67",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "Não se determina o término novo e, consequentemente, se haverá custo de extensão em relação à linha base."
    ],
    "motivo": "A garantia cobre a troca sem cobrança, mas não basta para determinar eventual custo de extensão.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A view não contém as relações de precedência e disponibilidade mencionadas como existentes em uma ficha relacional separada. Sem presumir essas relações, o impacto do aviso no término e no eventual custo de extensão permanece indeterminado."
}

