nto", "fonte_refs": ["f_a781"], "atributos": {}}, {"id": "n_7b42", "tipo": "atividade", "nome": "Preparar suporte", "fonte_refs": ["f_a781"], "atributos": {}}, {"id": "n_914b", "tipo": "pessoa", "nome": "Lia documental", "fonte_refs": ["f_a781"], "atributos": {}}, {"id": "n_ae50", "tipo": "marco", "nome": "Liberar estação", "fonte_refs": ["f_a781"], "atributos": {}}, {"id": "n_c196", "tipo": "atividade", "nome": "Usinar corpo", "fonte_refs": ["f_a781"], "atributos": {}}, {"id": "n_f8a3", "tipo": "atividade", "nome": "Ensaiar circuito", "fonte_refs": ["f_a781"], "atributos": {}}], "atividades": [{"id": "n_05ed", "entidade_id": "n_05ed", "duracao": {"estado": "exato", "valor": 3, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_ed3b48", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}, {"id": "n_21dc", "entidade_id": "n_21dc", "duracao": {"estado": "exato", "valor": 3, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_45f356", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}, {"id": "r_0cd9", "tipo": "nao_antes", "valor_dia": 8, "fonte_refs": ["f_36c2"]}]}, {"id": "n_683f", "entidade_id": "n_683f", "duracao": {"estado": "exato", "valor": 1, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_5c2874", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}, {"id": "n_7b42", "entidade_id": "n_7b42", "duracao": {"estado": "exato", "valor": 2, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_0daec2", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}, {"id": "n_ae50", "entidade_id": "n_ae50", "duracao": {"estado": "exato", "valor": 0, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_dcf8b0", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}, {"id": "n_c196", "entidade_id": "n_c196", "duracao": {"estado": "exato", "valor": 4, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_048381", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}, {"id": "n_f8a3", "entidade_id": "n_f8a3", "duracao": {"estado": "exato", "valor": 2, "unidade": "dia_corrido", "fonte_refs": ["f_a781"]}, "restricoes_contratuais": [{"id": "r_35e5fd", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_36c2"]}]}], "fontes": [{"id": "f_36c2", "documento_id": "d_32d1", "versao": "1.0", "localizador": "L02", "trecho": "Todas as atividades e o marco têm não antes D0. Emitir dossiê possui também restrição r_0cd9 não antes D8, por abertura contratual do protocolo. Estas são todas as restrições contratuais; não há componentes/requisitos de disponibilidade. A ficha d_a70f contém todas as precedências. A pessoa não altera quantitativos por mera anotação. Referência fixa do escopo: término D12; custo R$1.650,00. Avisos são isolados e alteram apenas o expressamente indicado."}, {"id": "f_493d", "documento_id": "d_540c", "versao": "1.0", "localizador": "L01", "trecho": "Apoio p_a84d incide uma única vez de D0 ao fim de liberar estação n_ae50. Cobertura contratada de 10 dias e taxa R$75 por dia extra. Fixo R$500; na base D12 há 2 dias de extensão = R$150, total R$650. Política sem_credito: antecipação preserva o valor base contratado de R$650; somente aditivo expresso pode autorizar recalcular extensão com crédito. As seis parcelas fixas não variam com prazo."}, {"id": "f_a781", "documento_id": "d_32d1", "versao": "1.0", "localizador": "L01", "trecho": "Projeto fictício Estação Nácar q_d92a. Prospectivo D0, dias corridos inteiros [início,fim), BRL em centavos. Sem progresso nem disputa de recursos. Entregas: preparar suporte n_7b42 (2 dias), usinar corpo n_c196 (4), integrar estação n_05ed (3), ensaiar circuito n_f8a3 (2), emitir dossiê n_21dc (3), inspecionar conjunto n_683f (1), liberar estação n_ae50 (marco 0). Lia documental n_914b é pessoa sem duração. Todas as entregas estão nesta lista."}, {"id": "f_b915", "documento_id": "d_70ec", "versao": "1.0", "localizador": "L01", "trecho": "Obrigações fixas únicas: p_8d30 preparar suporte R$100; p_c250 usinar R$200; p_91f6 integrar R$300; p_7c64 ensaiar R$200; p_2ca1 dossiê R$100; p_e504 inspecionar R$100. Apoio exclusivo p_a84d R$650 inclui fixo R$500 mais R$150 de extensão já prevista. Essas obrigações, o apoio e ajustes expressos nos avisos esgotam custos: sem outros tributos, multas ou incidências; preço de venda não integra o escopo. Parcelas não se repetem por caminho."}, {"id": "f_f2afea", "documento_id": "d_8335b1", "versao": "1.0", "localizador": "L01", "trecho": "O processo de usinar corpo n_c196 precisa ser redefinido: a duração nova não foi fixada e pode ser qualquer inteiro não negativo; não presumir os 4 dias antigos nem um mínimo superior a zero. Há cobrança direta única adicional de R$25,00, obrigação p_12d8, não incluída na base. As demais condições, inclusive dossiê D8, duração3 e apoio sem crédito, permanecem."}], "evento": {"evento_id": "e_d14f98", "relato": "O processo de usinar corpo n_c196 precisa ser redefinido: a duração nova não foi fixada e pode ser qualquer inteiro não negativo; não presumir os 4 dias antigos nem um mínimo superior a zero. Há cobrança direta única adicional de R$25,00, obrigação p_12d8, não incluída na base. As demais condições, inclusive dossiê D8, duração3 e apoio sem crédito, permanecem.", "origem": {"autor": "Equipe fictícia Estação Nácar", "documento_id": "d_8335b1", "data_registro": "D0"}, "instante_observacao": 0, "escopo": "Estação Nácar completa: seis atividades, marco e sete obrigações; prospectivo D0", "lacunas": []}}, "relacoes_texto": "relacoes: {"destino_id": "n_05ed", "fonte_refs": [{"fonte_id": "f_7d2f", "localizador": "L01"}], "id": "l_14a3e9", "lag_dias": 0, "origem_id": "n_c196", "tipo": "precede_FS"}
