    "valor": 12,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o término em D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_7d2f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A nova duração de Usinar corpo não foi fixada e pode ser qualquer inteiro não negativo; assim, o término pode ser D12 ou posterior, sem limite máximo informado."
    ],
    "motivo": "As precedências e a restrição D8 do dossiê sustentam término mínimo D12, mas a duração não fixada de Usinar corpo impede determinar o término final.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_7d2f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A variação pode ser zero ou positiva, e sua magnitude depende da duração não fixada de Usinar corpo."
    ],
    "motivo": "O término novo não pode ser anterior a D12, mas pode permanecer em D12 ou atrasar; portanto, não há sinal estrito nem magnitude determinados.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declara custo de R$1.650,00, equivalente a 165000 centavos.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O custo pode incluir extensão adicional do apoio, dependente do término novo, que não é determinável sem a duração redefinida."
    ],
    "motivo": "Há cobrança direta adicional de 2500 centavos; o apoio preserva o valor base se não houver atraso, mas cobra por dias adicionais de extensão.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_7d2f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A magnitude total não é determinável: o aumento é de pelo menos 2500 centavos e pode incluir extensão adicional do apoio se houver atraso."
    ],
    "motivo": "A cobrança direta de 2500 centavos é certa; o término não antecipa a linha base, e eventual atraso pode aumentar ainda mais o custo do apoio.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A redefinição deixa a duração de Usinar corpo indeterminada. Com as precedências e a restrição do dossiê em D8, o término final pode ser D12 ou posterior. O custo aumenta pelo menos 2500 centavos da cobrança direta; eventual atraso também pode gerar extensão adicional do apoio."
}

