      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_7d2f",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O atraso eventual além de D12 depende da duração não fixada de usinagem e, portanto, não se determina o custo adicional de apoio."
    ],
    "motivo": "Há cobrança direta de 2500 centavos. Além disso, cada dia de atraso além de D12 acrescenta 7500 centavos ao apoio; como o atraso não é conhecido, o custo total não é exato.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_7d2f",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A magnitude depende do número de dias de atraso além de D12, que não pode ser determinado sem a duração redefinida de usinagem."
    ],
    "motivo": "A cobrança direta aumenta o custo em 2500 centavos, no mínimo. Se houver atraso além de D12, o apoio acrescenta 7500 centavos por dia.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A sequência de precedências permite término em D12 ou posterior, conforme a duração ainda não fixada de usinar corpo. O custo aumenta pelo menos 2500 centavos da cobrança direta; eventual atraso além de D12 também aumenta o apoio em 7500 centavos por dia."
}

