{"execucao_id": "etapa9-v06-90-BHT-R2-20261027-k_f04b-T-1", "projeto_id": "q_6b20", "versao": "v1.0", "evento_id": "e_92a7", "view_hash": "596d5abaff6356da958a1fabfed40eb81a72c8743820c3e7041a31e692861bb1", "view": {"schema_version": "1.0-view", "condicao": "T", "comum": {"projeto_id": "q_6b20", "versao_projeto": "v1.0", "nome": "Bancada Íris", "calendario": {"id": "cal_0a62", "origem_label": "D0", "unidade": "dia_corrido", "indice_inicial": 0, "fonte_refs": ["f_04054cfee1"]}, "moeda": "BRL", "unidade_monetaria": "BRL_centavo", "marco_final_id": "n_e659", "linha_base_declarada": {"fim_dia": 10, "custo_centavos": 500000, "fonte_refs": ["f_bbb437fd83"]}, "parcelas_base": [{"id": "p_34ad", "escopo_id": "q_6b20", "descricao": "Receber cartucho", "valor_centavos": 100000, "moeda": "BRL", "fonte_refs": ["f_8ca6cc3cb4"]}, {"id": "p_40f2", "escopo_id": "q_6b20", "descricao": "Montar bancada", "valor_centavos": 150000, "moeda": "BRL", "fonte_refs": ["f_8ca6cc3cb4"]}, {"id": "p_6e15", "escopo_id": "q_6b20", "descricao": "Testar bancada", "valor_centavos": 100000, "moeda": "BRL", "fonte_refs": ["f_8ca6cc3cb4"]}, {"id": "p_91b7", "escopo_id": "q_6b20", "descricao": "Preparar carcaça", "valor_centavos": 50000, "moeda": "BRL", "fonte_refs": ["f_8ca6cc3cb4"]}, {"id": "p_c8a0", "escopo_id": "q_6b20", "descricao": "Apoio do projeto", "valor_centavos": 100000, "moeda": "BRL", "fonte_refs": ["f_8ca6cc3cb4"]}], "entidades": [{"id": "n_08df", "tipo": "atividade", "nome": "Testar bancada", "fonte_refs": ["f_359bae5d73"], "atributos": {}}, {"id": "n_42be", "tipo": "atividade", "nome": "Receber cartucho", "fonte_refs": ["f_359bae5d73"], "atributos": {}}, {"id": "n_73fa", "tipo": "fornecedor", "nome": "Oficina Nimbo", "fonte_refs": ["f_11ebeff90b"], "atributos": {}}, {"id": "n_915c", "tipo": "atividade", "nome": "Preparar carcaça", "fonte_refs": ["f_359bae5d73"], "atributos": {}}, {"id": "n_a367", "tipo": "atividade", "nome": "Montar bancada", "fonte_refs": ["f_359bae5d73"], "atributos": {}}, {"id": "n_c820", "tipo": "componente", "nome": "Cartucho", "fonte_refs": ["f_11ebeff90b"], "atributos": {"disponibilidade": {"estado": "exato", "valor": 2, "unidade": "dia_corrido", "fonte_refs": ["f_11ebeff90b"]}}}, {"id": "n_e659", "tipo": "marco", "nome": "Entregar bancada", "fonte_refs": ["f_359bae5d73"], "atributos": {}}], "atividades": [{"id": "n_08df", "entidade_id": "n_08df", "duracao": {"estado": "exato", "valor": 2, "unidade": "dia_corrido", "fonte_refs": ["f_359bae5d73"]}, "restricoes_contratuais": [{"id": "r_3f39d5", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_a2c707b9d7"]}]}, {"id": "n_42be", "entidade_id": "n_42be", "duracao": {"estado": "exato", "valor": 1, "unidade": "dia_corrido", "fonte_refs": ["f_359bae5d73"]}, "restricoes_contratuais": [{"id": "r_559aea", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_a2c707b9d7"]}]}, {"id": "n_915c", "entidade_id": "n_915c", "duracao": {"estado": "exato", "valor": 5, "unidade": "dia_corrido", "fonte_refs": ["f_359bae5d73"]}, "restricoes_contratuais": [{"id": "r_df7e70", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_a2c707b9d7"]}]}, {"id": "n_a367", "entidade_id": "n_a367", "duracao": {"estado": "exato", "valor": 3, "unidade": "dia_corrido", "fonte_refs": ["f_359bae5d73"]}, "restricoes_contratuais": [{"id": "r_6b23c0", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_a2c707b9d7"]}]}, {"id": "n_e659", "entidade_id": "n_e659", "duracao": {"estado": "exato", "valor": 0, "unidade": "dia_corrido", "fonte_refs": ["f_359bae5d73"]}, "restricoes_contratuais": [{"id": "r_08f271", "tipo": "nao_antes", "valor_dia": 0, "fonte_refs": ["f_a2c707b9d7"]}]}], "fontes": [{"id": "f_04054cfee1", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L01", "trecho": "Projeto fictício Bancada Íris, ID q_6b20, versão v1.0. Planejamento prospectivo no D0; dias corridos inteiros, intervalos [início,fim), BRL em centavos. Não há execução iniciada, disputa de recursos, feriados ou frações de dia."}, {"id": "f_11ebeff90b", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L02", "trecho": "O fornecedor Oficina Nimbo (n_73fa) fornece o componente cartucho (n_c820); a identificação de fornecimento é contextual. O lote original do cartucho estará disponível em D2."}, {"id": "f_12e7f172f0", "documento_id": "d_6d38", "versao": "1.0", "localizador": "L01", "trecho": "O responsável pelo preparo da carcaça n_915c formalizou um novo procedimento de quatro dias, substituindo os cinco dias do plano. O fornecedor de recebimento concedeu crédito definitivo de R$100,00 sobre a parcela p_34ad, por ajuste comercial associado a este procedimento, sem nova obrigação. Não há outros custos desse ajuste; cartucho original e todos os demais atributos e condições permanecem."}, {"id": "f_259da44f35", "documento_id": "d_482e", "versao": "1.0", "localizador": "L03", "trecho": "Um aviso pode documentar aditivo ou crédito sobre obrigação identificada, válido apenas no cenário desse aviso; não altera retroativamente a referência D0. Valores adicionais expressamente citados não estão incluídos no orçamento original. Não inferir créditos sem cláusula."}, {"id": "f_359bae5d73", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L03", "trecho": "Receber cartucho (n_42be) dura 1 dia; preparar carcaça (n_915c) dura 5 dias; montar bancada (n_a367) dura 3 dias no procedimento padrão; testar bancada (n_08df) dura 2 dias; entregar bancada (n_e659) é marco de duração 0 e único término final."}, {"id": "f_52a04b86dd", "documento_id": "d_8c23", "versao": "1.0", "localizador": "L02", "trecho": "O lote original segue procedimento padrão e não requer readequação. Para lotes substitutos a aceitação não é presumida por disponibilidade, preço, transporte, existência de laudo ou seleção comercial. Os avisos são a única evidência de aceite específica do lote."}, {"id": "f_77c5d27cd0", "documento_id": "d_59c1", "versao": "1.0", "localizador": "L02", "trecho": "Além de dez dias, cobrar R$100,00 por dia corrido de extensão até o marco final. Não há outras incidências. A regra é sobre um único intervalo do projeto, nunca por atividade ou caminho."}, {"id": "f_8ca6cc3cb4", "documento_id": "d_482e", "versao": "1.0", "localizador": "L01", "trecho": "As parcelas únicas são: p_34ad receber cartucho R$1.000,00; p_91b7 preparar carcaça R$500,00; p_40f2 montar bancada R$1.500,00; p_6e15 testar bancada R$1.000,00; p_c8a0 apoio R$1.000,00. Não somar novamente uma parcela ao mencioná-la em outra atividade."}, {"id": "f_a2c707b9d7", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L04", "trecho": "Todas as quatro atividades e o marco têm restrição contratual não antes de D0. Disponibilidade do componente não é duração de atividade. Datas planejadas não acrescentam restrições de início."}, {"id": "f_aa2f56bbb7", "documento_id": "d_59c1", "versao": "1.0", "localizador": "L03", "trecho": "Política sem_credito: o compromisso fixo permanece mesmo se o marco antecipar; nenhuma devolução por dias não usados. Uma dispensa de extensão ou crédito exige aditivo expresso. A referência D0 contém zero dias de extensão."}, {"id": "f_b1694cb6da", "documento_id": "d_59c1", "versao": "1.0", "localizador": "L01", "trecho": "A obrigação p_c8a0 é exclusiva da bancada: R$1.000,00 fixos cobrem dez dias contratados de D0 até D10 exclusivo. O intervalo de incidência é de D0 ao marco entregar bancada (n_e659)."}, {"id": "f_bbb437fd83", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L06", "trecho": "O cronograma de referência termina em D10; orçamento de referência R$5.000,00. Estes números são linha base fixa para comparação de cada aviso isolado; os avisos não se acumulam. Salvo alterações expressas, todas as condições do plano e dos contratos permanecem."}, {"id": "f_d96520b3de", "documento_id": "d_71ba", "versao": "1.0", "localizador": "L05", "trecho": "Essas quatro atividades e o marco esgotam as entregas obrigatórias deste escopo. A ficha relacional d_aa83 esgota precedências e requisitos de disponibilidade. Não existem requisitos adicionais de liberação."}, {"id": "f_e3f0ade479", "documento_id": "d_8c23", "versao": "1.0", "localizador": "L01", "trecho": "Na montagem (n_a367) com lote substituto, se houver laudo de equivalência aceito pela engenharia, manter o procedimento padrão de três dias, sem cobrança de readequação. Sem essa aceitação, aguardar definição técnica: não estimar duração nem custo de readequação."}, {"id": "f_e63d1b2e94", "documento_id": "d_482e", "versao": "1.0", "localizador": "L02", "trecho": "Essas cinco parcelas e os ajustes expressamente autorizados nos avisos e no contrato de apoio esgotam os custos deste escopo: sem multas, tributos, fretes, juros, outras diárias ou custos de ociosidade. Não existe preço de venda neste orçamento. Alterações de prazo não mudam as quatro parcelas fixas."}], "evento": {"evento_id": "e_92a7", "relato": "O responsável pelo preparo da carcaça n_915c formalizou um novo procedimento de quatro dias, substituindo os cinco dias do plano. O fornecedor de recebimento concedeu crédito definitivo de R$100,00 sobre a parcela p_34ad, por ajuste comercial associado a este procedimento, sem nova obrigação. Não há outros custos desse ajuste; cartucho original e todos os demais atributos e condições permanecem.", "origem": {"autor": "Equipe fictícia Bancada Íris", "documento_id": "d_6d38", "data_registro": "D0"}, "instante_observacao": 0, "escopo": "Bancada Íris completa; evento único prospectivo", "lacunas": []}}, "relacoes_texto": "relacoes: {"destino_id": "n_c820", "fonte_refs": [{"fonte_id": "f_11ebeff90b", "localizador": "L02"}], "id": "l_0f81", "origem_id": "n_73fa", "tipo": "fornece"}
relacoes: {"destino_id": "n_a367", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_263e", "lag_dias": 0, "origem_id": "n_915c", "tipo": "precede_FS"}
relacoes: {"destino_id": "n_e659", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_8a19", "lag_dias": 0, "origem_id": "n_08df", "tipo": "precede_FS"}
relacoes: {"destino_id": "n_a367", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_938a", "lag_dias": 0, "origem_id": "n_42be", "tipo": "precede_FS"}
relacoes: {"destino_id": "n_c820", "fonte_refs": [{"fonte_id": "f_aab5d508ec", "localizador": "L01"}], "id": "l_b6d2", "origem_id": "n_42be", "tipo": "requer"}
relacoes: {"destino_id": "n_08df", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_d405", "lag_dias": 0, "origem_id": "n_a367", "tipo": "precede_FS"}
transferencias: {"fonte_refs": [{"fonte_id": "f_aab5d508ec", "localizador": "L01"}], "id": "t_5f83", "operacao": "disponibilidade_para_restricao", "origem_atributo": "disponibilidade", "relacao_id": "l_b6d2", "restricao_destino_id": "r_d61b"}
fontes: {"documento_id": "d_aa83", "id": "f_aab5d508ec", "localizador": "L01", "trecho": "n_42be receber cartucho requer n_c820 cartucho. Somente neste requisito, a disponibilidade do cartucho determina uma restrição de liberação adicional em receber cartucho, preservando o não antes de D0. A liberação efetiva é o máximo das restrições ativas.", "versao": "1.0"}
